/bin/zsh -lc "cat > src/app.js <<'EOF'
import {seed,labels as initialLabels,matches} from './data.js';
const paths={menu:'M4 6h16M4 12h16M4 18h16',search:'m21 21-5-5M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0',inbox:'M4 4h16l2 10v6H2v-6L4 4Zm-2 10h6l2 3h4l2-3h6',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',send:'m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13',file:'M14 2H5v20h14V7l-5-5Zm0 0v6h5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',down:'m8 10 4 4 4-4',right:'m10 6 6 6-6 6',left:'m14 6-6 6 6 6',plus:'M12 5v14M5 12h14',edit:'m16 3 5 5-12 12-6 1 1-6L16 3ZM14 5l5 5',tag:'M3 3h8l10 10-8 8L3 11V3ZM7 7h.01',archive:'M3 3h18v5H3zM5 8v13h14V8M9 12h6',mail:'M3 5h18v14H3zM3 5l9 7 9-7',refresh:'M20 8a8 8 0 1 0 0 8M20 3v5h-5',more:'M5 12h.01M12 12h.01M19 12h.01',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',grid:'M4 4h2v2H4zM11 4h2v2h-2zM18 4h2v2h-2zM4 11h2v2H4zM11 11h2v2h-2zM18 11h2v2h-2zM4 18h2v2H4zM11 18h2v2h-2zM18 18h2v2h-2z',sliders:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 3a4 4 0 1 1 0 8 4 4 0 0 1 0-8M17 4a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-4',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12M6 18 18 6',back:'M20 12H4m6-6-6 6 6 6',reply:'m9 5-6 6 6 6M3 11h11a7 7 0 0 1 7 7',clip:'m8 12 7-7a4 4 0 0 1 6 6L10 22a6 6 0 0 1-8-8L13 3',expand:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5',minus:'M5 12h14',check:'m5 12 4 4L19 6',calendar:'M3 5h18v16H3zM7 2v6M17 2v6M3 10h18M7 14h3v3H7z',bulb:'M9 18h6M9 21h6M8 15a7 7 0 1 1 8 0l-1 3H9l-1-3',checkcircle:'m7 12 3 3 7-7M22 12a10 10 0 1 1-5-8',image:'M3 3h18v18H3zM3 17l6-6 5 5 3-3 4 4M15 7h.01',link:'m10 14 4-4M8 16l-2 2a4 4 0 0 1-6-6l6-6M16 8l2-2a4 4 0 0 1 6 6l-6 6',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4'};
const icon=(n,cls='')=>"'`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.mail}"/></svg>`;
const esc=s=>String(s??'"'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
let saved;try{saved=JSON.parse(localStorage.getItem('gpt6-mail'))}catch{};
let mail=saved?.mail||seed(),labels=saved?.labels||initialLabels,view='Inbox',category='Primary',query='',selected=new Set(),opened=null,compose=null,popup='',toastTimer,undoState,side=false,compact=saved?.compact||false;
const persist=()=>localStorage.setItem('gpt6-mail',JSON.stringify({mail,labels,compact}));
const btn=(n,title,act,extra='')=>"'`<button class="icon-btn ${extra}" title="${title}" aria-label="${title}" data-action="${act}">${icon(n)}</button>`;
function filtered(){return mail.filter(m=>query?m.folder!=='"'trash'&&matches(m,query):view==='Starred'?m.star&&m.folder"'!=='"'trash':view==='All mail'?m.folder"'!=='"'trash'&&m.folder"'!=='"'drafts':labels.includes(view)?m.labels.includes(view)&&m.folder"'!=='"'trash':m.folder===view.toLowerCase()).filter(m=>query||view"'!=='"'Inbox'||m.category===category)}
function navigate(v){view=v;query='';opened=null;selected.clear();popup='';side=false;render()}
function notice(s,undo=false){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.innerHTML="'`${esc(s)} ${undo?'"'<button data-action=\"undo\">Undo</button>':''}"'${btn('"'close','Dismiss','dismiss')}"'`;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),5500)}
function mutate(ids,fn,msg){undoState=JSON.stringify(mail);mail=mail.map(m=>ids.includes(m.id)?fn({...m}):m);persist();selected.clear();if(opened&&!filtered().some(m=>m.id===opened))opened=null;render();if(msg)notice(msg,true)}
function render(){const list=filtered(),unread=mail.filter(m=>m.folder==='"'inbox'&&"'!m.read).length;document.getElementById('"'app').innerHTML="'`
<header><div class="brand">${btn('"'menu','Toggle navigation','sidebar')}<span class=\"brand-mark\"><svg viewBox=\"0 0 36 28\"><path d=\"M3 23V5l15 11L33 5v18\" fill=\"none\" stroke=\"#5488ec\" stroke-width=\"5\" stroke-linejoin=\"round\"/><path d=\"m3 5 15 11L33 5\" fill=\"none\" stroke=\"#e96c5c\" stroke-width=\"5\"/><path d=\"M33 5v18\" stroke=\"#63a475\" stroke-width=\"5\"/><path d=\"M3 5v7\" stroke=\"#f4bd50\" stroke-width=\"5\"/></svg></span><h1>GPT-6</h1></div><div class=\"search\">"'${icon('"'search')}<input id=\"search\" aria-label=\"Search mail\" placeholder=\"Search mail\" value=\""'${esc(query)}">${query?btn('"'close','Clear search','clear-search'):btn('sliders','Advanced search','search-options')}</div><div class=\"header-actions\"><span class=\"status-dot\"></span><span class=\"status-label\">Active</span>"'${btn('"'down','Status','status')}"'${btn('"'help','Help & keyboard shortcuts','help')}"'${btn('"'settings','Settings','settings')}"'${btn('"'grid','Quick access','apps')}<button class=\"avatar account-avatar\" data-action=\"account\" aria-label=\"Account: Jamie Parker\">J</button></div></header>
<div class=\"shell\"><aside class=\"sidebar "'${side?'"'mobile-open':''}\"><button class=\"compose-button\" data-action=\"compose\">"'${icon('"'edit')}<span>Compose</span></button><nav>"'${[['"'Inbox','inbox',unread],['Starred','star'],['Snoozed','clock'],['Sent','send'],['Drafts','file',mail.filter(m=>m.folder==='drafts').length],['Trash','trash'],['All mail','mail']].map(([v,i,c])=>"'`<button class="nav-item ${view===v&&!query?'"'active':''}\" data-view=\""'${v}">${icon(i)}<span>${v}</span>${c?`<b>${c}</b>`:'"''}</button>"'`).join('"'')}</nav><div class=\"label-heading\">Labels"'${btn('"'plus','Create label','new-label')}</div><div class=\"label-nav\">"'${labels.map((l,i)=>`<button class="nav-item ${view===l?'"'active':''}\" data-view=\""'${esc(l)}">${icon('"'tag','label-color-'+i%4)}<span>"'${esc(l)}</span></button>`).join('"'')}</div><div class=\"storage\"><div>"'${icon('"'cloud')}<span>0.8 GB of 15 GB used</span></div><div class=\"storage-track\"><i></i></div><button data-action=\"storage\">Manage storage "'${icon('"'right')}</button></div><div class=\"sidebar-footer\">Made for a little more focus.</div></aside>
<main class=\"mail-panel "'${compact?'"'compact':''}\">"'${opened?reading(mail.find(m=>m.id===opened)):inbox(list)}</main><aside class="utility-rail">${btn('"'calendar','Calendar','calendar')}"'${btn('"'bulb','Keep notes','notes')}"'${btn('"'checkcircle','Tasks','tasks')}"'${btn('"'users','Contacts','contacts')}<span></span>"'${btn('"'plus','Quick access','apps')}<div class=\"rail-bottom\">"'${btn('"'right','Hide side panel','rail')}</div></aside></div>"'${compose?composeHTML():'"''}"'${popup?popupHTML():'"''}"'`;bindInputs()}
function inbox(list){return `<div class="toolbar"><div class="toolbar-left"><input type="checkbox" id="select-all" aria-label="Select all messages" ${list.length&&list.every(m=>selected.has(m.id))?'"'checked':''}>"'${btn('"'down','Selection options','selection')}"'${selected.size?`${btn('"'archive','Archive selected','archive')}"'${btn('"'trash','Delete selected','delete')}"'${btn('"'mail','Mark unread','unread')}"'${btn('"'clock','Snooze selected','snooze')}"'${btn('"'tag','Label selected','label')}"'`:`${btn('"'refresh','Refresh inbox','refresh')}"'${btn('"'more','More actions','more')}"'`}</div><div class="toolbar-right">${selected.size?`<span>${selected.size} selected</span>`:'"''}<span>"'${list.length?'"'1–'+list.length+' of '+list.length:'0 messages'}</span>"'${btn('"'left','Previous page','previous','disabled')}"'${btn('"'right','Next page','next','disabled')}"'${btn('"'down','Display density','density')}</div></div>"'${view==='"'Inbox'&&"'!query?`<div class="categories">${[['"'Primary','inbox'],['Promotions','tag'],['Social','users'],['Updates','info']].map(([c,i])=>"'`<button class="category ${category===c?'"'chosen':''}\" data-category=\""'${c}">${icon(i)}<div><span>${c}</span>${c==='"'Promotions'?'<small>Offers, inspiration & more</small>':c==='Updates'?'<small>Notion, Linear, Figma</small>':''}</div>"'${c==='"'Updates'?'<b class=\"new-count\">2 new</b>':''}</button>"'`).join('"'')}</div>"'`:`<div class="folder-title"><h2>${query?'"'Search results':esc(view)}</h2><span>"'${query?`Results for “${esc(query)}”`:`${list.length} conversations`}</span></div>`}<div class="messages">${list.length?list.map(row).join('"''):"'`<div class="empty">${icon(query?'"'search':'inbox')}<h2>"'${query?'"'No matching conversations':'All clear here'}</h2><p>"'${query?'"'Try another keyword, sender, or subject.':'There’s no mail in '+esc(view.toLowerCase())+' right now.'}</p>"'${query?'"'<button class=\"outline\" data-action=\"clear-search\">Clear search</button>':''}</div>"'`}</div><footer class="mail-footer"><span>${icon('"'lock')} Your space. Your conversations.</span><span>Last account activity: just now <button data-action=\"account\">Details</button></span></footer>"'`}
function row(m){return `<div class="mail-row ${!m.read?'"'unread':''} "'${selected.has(m.id)?'"'selected':''}\" data-id=\""'${m.id}" tabindex="0" role="button" aria-label="${esc(m.sender+'"': '+m.subject)}\"><div class=\"row-controls\"><input type=\"checkbox\" data-select=\""'${m.id}" aria-label="Select ${esc(m.subject)}" ${selected.has(m.id)?'"'checked':''}><button class=\"star "'${m.star?'"'starred':''}\" data-star=\""'${m.id}" aria-label="${m.star?'"'Unstar':'Star'} "'${esc(m.subject)}">${icon('"'star')}</button></div><div class=\"sender\">"'${esc(m.sender)}${m.count>1?` <small>${m.count}</small>`:'"''}"'${m.folder==='"'drafts'?'<em>Draft</em>':''}</div><div class=\"mail-content\"><div class=\"message-line\">"'${m.labels.map(l=>`<span class="label label-${labels.indexOf(l)%4}">${esc(l)}</span>`).join('"'')}<span class=\"subject\">"'${esc(m.subject)}</span><span class="preview"> <span class="dash">—</span> ${esc(m.preview)}</span></div>${m.attachment?`<span class="attachment-chip">${icon('"'file')} "'${esc(m.attachment)}</span>`:'"''}</div><time>"'${m.time}</time><div class="row-hover">${btn('"'archive','Archive','row-archive-'+m.id)}"'${btn('"'trash','Delete','row-delete-'+m.id)}"'${btn('"'mail',m.read?'Mark unread':'Mark read','row-read-'+m.id)}"'${btn('"'clock','Snooze','row-snooze-'+m.id)}</div></div>"'`}
function reading(m){if(!m)return '"'';return "'`<div class="toolbar"><div class="toolbar-left">${btn('"'back','Back to mailbox','back')}<span class=\"separator\"></span>"'${btn('"'archive','Archive','archive')}"'${btn('"'trash','Move to trash','delete')}<span class=\"separator\"></span>"'${btn('"'mail','Mark unread','unread')}"'${btn('"'clock','Snooze','snooze')}"'${btn('"'tag','Add label','label')}"'${btn('"'more','More actions','more')}</div><div class=\"toolbar-right\"><span>"'${filtered().findIndex(x=>x.id===m.id)+1} of ${filtered().length}</span>${btn('"'left','Previous conversation','prev-message')}"'${btn('"'right','Next conversation','next-message')}</div></div><article class=\"conversation\"><div class=\"subject-heading\"><h2>"'${esc(m.subject)}</h2><span class="label neutral">${m.folder}</span></div>${m.count>1?`<div class="earlier" data-action="earlier">${icon('"'users')}<span>"'${m.count-1} earlier messages in this conversation</span>${icon('"'down')}</div>"'`:'"''}<div class=\"message-heading\"><div class=\"avatar sender-avatar\">"'${m.sender.slice(0,1)}</div><div class="sender-details"><b>${esc(m.sender)}</b><span>&lt;${esc(m.email)}&gt;</span><small>to ${esc(m.to)} ${icon('"'down')}</small></div><time>Sep 29, 2026, "'${m.time}</time><button class="star ${m.star?'"'starred':''}\" data-star=\""'${m.id}" aria-label="Star message">${icon('"'star')}</button>"'${btn('"'reply','Reply','reply')}</div><div class=\"message-body\"><p>Hi Jamie,</p><div>"'${esc(m.body).replaceAll('"'\\n','<br>')}</div>"'${m.attachment?`<div class="attachment-card"><div class="attachment-art">${icon('"'file')}<span>"'${m.attachment.split('"'.').pop().toUpperCase()}</span></div><div><b>"'${esc(m.attachment)}</b><small>248 KB · ${m.attachment.split('"'.').pop().toUpperCase()} file</small></div><button class=\"outline\" data-action=\"download\">Download</button></div>"'`:'"''}</div>"'${(m.replies||[]).map(r=>`<div class="sent-reply"><div class="avatar">J</div><div><b>Jamie Parker <small>&lt;jamie@studio.design&gt;</small></b><small>to ${esc(r.to)} · just now</small><p>${esc(r.body).replaceAll('"'\\n','<br>')}</p></div>"'${icon('"'check')}</div>"'`).join('"'')}<div class=\"reply-actions\"><button class=\"outline\" data-action=\"reply\">"'${icon('"'reply')} Reply</button><button class=\"outline\" data-action=\"forward\">"'${icon('"'send')} Forward</button></div></article>"'`}
function composeHTML(){return `<section class="compose-window ${compose.max?'"'maximized':''} "'${compose.min?'"'minimized':''}\" aria-label=\"Compose email\"><div class=\"compose-top\"><b>"'${compose.reply?'"'Reply':'New message'}</b><div>"'${btn('"'minus','Minimize compose','minimize')}"'${btn('"'expand','Expand compose','maximize')}"'${btn('"'close','Save and close draft','close-compose')}</div></div><form id=\"compose-form\"><div class=\"recipient-line\"><label for=\"recipient\">To</label><input id=\"recipient\" required type=\"email\" multiple placeholder=\"Recipients\" value=\""'${esc(compose.to)}" list="contact-list"><datalist id="contact-list">${mail.filter(m=>m.sender!=='"'me').slice(0,12).map(m=>"'`<option value="${esc(m.email)}">${esc(m.sender)}</option>`).join('"'')}</datalist><button type=\"button\" data-action=\"cc\">Cc</button><button type=\"button\" data-action=\"bcc\">Bcc</button></div>"'${compose.cc!==undefined?`<div class="recipient-line"><label>Cc</label><input id="cc" type="email" multiple value="${esc(compose.cc)}"></div>`:'"''}"'${compose.bcc!==undefined?`<div class="recipient-line"><label>Bcc</label><input id="bcc" type="email" multiple value="${esc(compose.bcc)}"></div>`:'"''}<input id=\"compose-subject\" placeholder=\"Subject\" aria-label=\"Subject\" value=\""'${esc(compose.subject)}"><textarea id="compose-body" placeholder="Write something good…" aria-label="Message body">${esc(compose.body)}</textarea>${compose.attachment?`<div class="compose-attachment">${icon('"'clip')}"'${esc(compose.attachment)}<button type="button" data-action="remove-attachment">×</button></div>`:'"''}<div class=\"compose-format\"><button type=\"button\" data-action=\"format-bold\" title=\"Insert bold text\"><b>B</b></button><button type=\"button\" data-action=\"format-italic\" title=\"Insert emphasis\"><i>I</i></button><button type=\"button\" data-action=\"format-list\" title=\"Insert list\">≡</button><span></span><small>Draft saved locally</small></div><div class=\"compose-bottom\"><button class=\"send-button\" type=\"submit\">Send "'${icon('"'send')}</button>"'${btn('"'clip','Attach file','attach')}"'${btn('"'link','Insert link','insert-link')}<input type=\"file\" id=\"file-input\" hidden><span></span>"'${btn('"'trash','Discard draft','discard')}</div></form></section>"'`}
function popupHTML(){const content={help:`<h2>A little faster, a little easier</h2><p>Your keyboard is welcome here.</p><div class="shortcut"><kbd>C</kbd> Compose a message</div><div class="shortcut"><kbd>/</kbd> Search your mail</div><div class="shortcut"><kbd>Esc</kbd> Close a conversation or dialog</div><p>Search supports <b>from:</b>, <b>label:</b>, <b>is:unread</b>, <b>is:starred</b>, and <b>has:attachment</b>.</p>`,settings:`<h2>Make yourself at home</h2><p>Display density</p><button class="setting-option" data-action="comfortable">${icon(compact?'"'plus':'checkcircle')} Comfortable <small>A little room to breathe</small></button><button class=\"setting-option\" data-action=\"compact\">"'${icon(compact?'"'checkcircle':'plus')} Compact <small>More conversations at a glance</small></button><p>Mail is saved automatically on this device.</p>"'`,account:`<div class="profile"><div class="avatar">J</div><h2>Hi, Jamie.</h2><p>jamie@studio.design</p><span class="local-badge">Personal workspace</span></div><p>This is your local mailbox. Your drafts, labels, and conversations stay saved in this browser.</p>`,label:`<h2>Label as</h2>${labels.map(l=>`<button class="setting-option" data-add-label="${esc(l)}">${icon('"'tag')} "'${esc(l)}</button>`).join('"'')}<button class=\"setting-option\" data-action=\"remove-labels\">Remove labels</button><button class=\"setting-option\" data-action=\"new-label\">"'${icon('"'plus')} Create new label</button>"'`, '"'new-label':"'`<h2>A place for everything</h2><p>Give your new label a name.</p><form id="label-form"><input name="label" required maxlength="30" placeholder="e.g. Inspiration" autofocus><button class="send-button">Create label</button></form>`,snooze:`<h2>Snooze until…</h2><p>Move this conversation out of your inbox.</p>${['"'Later today','Tomorrow morning','Next week'].map(s=>"'`<button class="setting-option" data-snooze="${s}">${icon('"'clock')} "'${s}</button>`).join('"'')}"'`,selection:`<h2>Select messages</h2>${['"'All','None','Read','Unread','Starred'].map(s=>"'`<button class="setting-option" data-selection="${s}">${s}</button>`).join('"'')}"'`,more:`<h2>More actions</h2><button class="setting-option" data-action="read-all">Mark all visible as read</button><button class="setting-option" data-action="restore">Move selected to Inbox</button><button class="setting-option" data-action="help">Keyboard shortcuts</button>`, '"'search-options':"'`<h2>Find just the thing</h2><form id="advanced-form"><label>From<input name="from" placeholder="Name or email address"></label><label>Has the words<input name="words" placeholder="Project, weekend, coffee…"></label><label class="check-label"><input type="checkbox" name="unread"> Unread only</label><label class="check-label"><input type="checkbox" name="attachment"> Has attachment</label><button class="send-button">Search mail</button></form>`,apps:`<h2>Your workspace</h2><div class="app-grid">${[['"'calendar','Calendar'],['notes','Notes'],['tasks','Tasks'],['contacts','Contacts']].map(([a,t])=>"'`<button data-action="${a}">${icon(a==='"'notes'?'bulb':a==='tasks'?'checkcircle':a==='contacts'?'users':'calendar')}<span>"'${t}</span></button>`).join('"'')}</div>"'`,calendar:`<h2>Tuesday, September 29</h2><p class="eyebrow">YOUR DAY, AT A GLANCE</p><div class="event"><b>10:00 – 10:30</b><h3>Morning team sync</h3><p>Studio · Google Meet</p></div><div class="event green"><b>14:00 – 15:00</b><h3>Website design review</h3><p>With Alex Morgan</p></div><p>A little room to focus in between.</p>`,notes:`<h2>A thought worth keeping</h2><textarea id="notes" class="notes" placeholder="Ideas, reminders, little things…">${esc(localStorage.getItem('"'gpt6-notes')||'')}</textarea><small>Saved automatically on this device</small>"'`,tasks:`<h2>A little progress</h2><form id="task-form"><input name="task" placeholder="Add a task" required><button class="send-button">Add</button></form><div id="task-list">${getTasks().map((t,i)=>`<label class="task ${t.done?'"'done':''}\"><input type=\"checkbox\" data-task=\""'${i}" ${t.done?'"'checked':''}>"'${esc(t.text)}</label>`).join('"'')}</div>"'`,contacts:`<h2>Your people</h2>${mail.filter(m=>['"'Alex Morgan','Sophie Chen','Emma Wilson','Noah Williams'].includes(m.sender)).map(m=>"'`<button class="contact" data-contact="${esc(m.email)}"><span class="avatar">${m.sender[0]}</span><span><b>${esc(m.sender)}</b><small>${esc(m.email)}</small></span>${icon('"'edit')}</button>"'`).join('"'')}"'`,storage:`<h2>Plenty of room to grow</h2><p>0.8 GB of 15 GB used</p><div class="storage-track"><i></i></div><p>Your local mailbox contains ${mail.length} conversations. Mail and drafts are stored on this device.</p>`,status:`<h2>Your availability</h2>${['"'Active','Do not disturb','Away'].map(s=>"'`<button class="setting-option" data-status="${s}">${icon(s==='"'Active'?'checkcircle':'clock')} "'${s}</button>`).join('"'')}"'`,earlier:`<h2>Earlier in the conversation</h2><p><b>Jamie Parker</b> · Sep 28</p><p>Thanks for taking this forward! I’m excited to see where we land. The direction we discussed feels right — let’s keep it clear and give the work room to breathe.</p><hr><p><b>${esc(mail.find(m=>m.id===opened)?.sender)}</b> · Sep 28</p><p>Absolutely. I’ll put together a few options and send them over tomorrow.</p>`};return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true">${btn('"'close','Close dialog','close-popup','modal-close')}"'${content[popup]||'"''}</section></div>"'`}
function getTasks(){try{return JSON.parse(localStorage.getItem('"'gpt6-tasks'))||[{text:'Review the new homepage designs',done:false},{text:'Send Q3 planning feedback',done:false},{text:'Book a table for Friday',done:true}]}catch{return []}}
