\"compose-bottom\"><button class=\"send-button\" type=\"submit\">Send "'${icon('"'send')}</button>"'${btn('"'clip','Attach file','attach')}"'${btn('"'link','Insert link','insert-link')}<input type=\"file\" id=\"file-input\" hidden><span></span>"'${btn('"'trash','Discard draft','discard')}</div></form></section>"'`}
function popupHTML(){const content={help:`<h2>A little faster, a little easier</h2><p>Your keyboard is welcome here.</p><div class="shortcut"><kbd>C</kbd> Compose a message</div><div class="shortcut"><kbd>/</kbd> Search your mail</div><div class="shortcut"><kbd>Esc</kbd> Close a conversation or dialog</div><p>Search supports <b>from:</b>, <b>label:</b>, <b>is:unread</b>, <b>is:starred</b>, and <b>has:attachment</b>.</p>`,settings:`<h2>Make yourself at home</h2><p>Display density</p><button class="setting-option" data-action="comfortable">${icon(compact?'"'plus':'checkcircle')} Comfortable <small>A little room to breathe</small></button><button class=\"setting-option\" data-action=\"compact\">"'${icon(compact?'"'checkcircle':'plus')} Compact <small>More conversations at a glance</small></button><p>Mail is saved automatically on this device.</p>"'`,account:`<div class="profile"><div class="avatar">J</div><h2>Hi, Jamie.</h2><p>jamie@studio.design</p><span class="local-badge">Personal workspace</span></div><p>This is your local mailbox. Your drafts, labels, and conversations stay saved in this browser.</p>`,label:`<h2>Label as</h2>${labels.map(l=>`<button class="setting-option" data-add-label="${esc(l)}">${icon('"'tag')} "'${esc(l)}</button>`).join('"'')}<button class=\"setting-option\" data-action=\"remove-labels\">Remove labels</button><button class=\"setting-option\" data-action=\"new-label\">"'${icon('"'plus')} Create new label</button>"'`, '"'new-label':"'`<h2>A place for everything</h2><p>Give your new label a name.</p><form id="label-form"><input name="label" required maxlength="30" placeholder="e.g. Inspiration" autofocus><button class="send-button">Create label</button></form>`,snooze:`<h2>Snooze until…</h2><p>Move this conversation out of your inbox.</p>${['"'Later today','Tomorrow morning','Next week'].map(s=>"'`<button class="setting-option" data-snooze="${s}">${icon('"'clock')} "'${s}</button>`).join('"'')}"'`,selection:`<h2>Select messages</h2>${['"'All','None','Read','Unread','Starred'].map(s=>"'`<button class="setting-option" data-selection="${s}">${s}</button>`).join('"'')}"'`,more:`<h2>More actions</h2><button class="setting-option" data-action="read-all">Mark all visible as read</button><button class="setting-option" data-action="restore">Move selected to Inbox</button><button class="setting-option" data-action="help">Keyboard shortcuts</button>`, '"'search-options':"'`<h2>Find just the thing</h2><form id="advanced-form"><label>From<input name="from" placeholder="Name or email address"></label><label>Has the words<input name="words" placeholder="Project, weekend, coffee…"></label><label class="check-label"><input type="checkbox" name="unread"> Unread only</label><label class="check-label"><input type="checkbox" name="attachment"> Has attachment</label><button class="send-button">Search mail</button></form>`,apps:`<h2>Your workspace</h2><div class="app-grid">${[['"'calendar','Calendar'],['notes','Notes'],['tasks','Tasks'],['contacts','Contacts']].map(([a,t])=>"'`<button data-action="${a}">${icon(a==='"'notes'?'bulb':a==='tasks'?'checkcircle':a==='contacts'?'users':'calendar')}<span>"'${t}</span></button>`).join('"'')}</div>"'`,calendar:`<h2>Tuesday, September 29</h2><p class="eyebrow">YOUR DAY, AT A GLANCE</p><div class="event"><b>10:00 – 10:30</b><h3>Morning team sync</h3><p>Studio · Google Meet</p></div><div class="event green"><b>14:00 – 15:00</b><h3>Website design review</h3><p>With Alex Morgan</p></div><p>A little room to focus in between.</p>`,notes:`<h2>A thought worth keeping</h2><textarea id="notes" class="notes" placeholder="Ideas, reminders, little things…">${esc(localStorage.getItem('"'gpt6-notes')||'')}</textarea><small>Saved automatically on this device</small>"'`,tasks:`<h2>A little progress</h2><form id="task-form"><input name="task" placeholder="Add a task" required><button class="send-button">Add</button></form><div id="task-list">${getTasks().map((t,i)=>`<label class="task ${t.done?'"'done':''}