function getTasks(){try{return JSON.parse(localStorage.getItem('"'gpt6-tasks'))||[{text:'Review the new homepage designs',done:false},{text:'Send Q3 planning feedback',done:false},{text:'Book a table for Friday',done:true}]}catch{return []}}
function bindInputs(){document.querySelector('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;opened=null;selected.clear();render();const el=document.querySelector('#search');el.focus();el.setSelectionRange(pos,pos)});document.querySelector('#select-all')?.addEventListener('change',e=>{selected=e.target.checked?new Set(filtered().map(m=>m.id)):new Set();render()});for(const [id,key]of [['recipient','to'],['compose-subject','subject'],['compose-body','body'],['cc','cc'],['bcc','bcc']])document.getElementById(id)?.addEventListener('input',e=>{compose[key]=e.target.value;saveDraft()});document.querySelector('#compose-form')?.addEventListener('submit',send);document.querySelector('#file-input')?.addEventListener('change',e=>{if(e.target.files[0]){compose.attachment=e.target.files[0].name;saveDraft();render()}});document.querySelector('#label-form')?.addEventListener('submit',e=>{e.preventDefault();const l=new FormData(e.target).get('label').trim();if("'!l||labels.some(x=>x.toLowerCase()===l.toLowerCase()))return notice('"'Choose a unique label name');labels.push(l);persist();popup='';render();notice('Label created')});document.querySelector('#advanced-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);query=[f.get('from')?'from:'+f.get('from'):'',f.get('words'),f.get('unread')?'is:unread':'',f.get('attachment')?'has:attachment':''].filter(Boolean).join(' ');popup='';opened=null;render()});document.querySelector('#notes')?.addEventListener('input',e=>localStorage.setItem('gpt6-notes',e.target.value));document.querySelector('#task-form')?.addEventListener('submit',e=>{e.preventDefault();const tasks=getTasks();tasks.push({text:new FormData(e.target).get('task'),done:false});localStorage.setItem('gpt6-tasks',JSON.stringify(tasks));render()})}
function saveDraft(){if("'!compose)return;let d=mail.find(m=>m.id===compose.id);if(!d){d={id:compose.id,sender:'"'me',email:'jamie@studio.design',time:'Draft',labels:[],read:true,star:false,count:1,category:'Primary',folder:'drafts',replies:[]};mail.unshift(d)}Object.assign(d,{to:compose.to,subject:compose.subject||'(no subject)',body:compose.body,preview:compose.body,attachment:compose.attachment,cc:compose.cc,bcc:compose.bcc});persist()}
