document.addEventListener('click',e=>{const target=e.target.closest('button,[data-id],[data-select],[data-task]');if(e.target.classList.contains('modal-backdrop')){popup='';render();return}if("'!target)return;if(target.dataset.action){e.preventDefault();action(target.dataset.action);return}if(target.dataset.view)return navigate(target.dataset.view);if(target.dataset.category){category=target.dataset.category;selected.clear();render();return}if(target.dataset.star){const m=mail.find(m=>m.id===+target.dataset.star);m.star=!m.star;persist();render();return}if(target.dataset.select){const id=+target.dataset.select;selected.has(id)?selected.delete(id):selected.add(id);render();return}if(target.dataset.addLabel){const l=target.dataset.addLabel;popup='"'';return mutate(ids(),m=>({...m,labels:[...new Set([...m.labels,l])]}),'Label added')}if(target.dataset.snooze){const until=target.dataset.snooze;popup='';return mutate(ids(),m=>({...m,folder:'snoozed',snoozedUntil:until}),'Snoozed until '+until.toLowerCase())}if(target.dataset.selection){const s=target.dataset.selection;selected=new Set(filtered().filter(m=>s==='All'||s==='Read'&&m.read||s==='Unread'&&"'!m.read||s==='"'Starred'&&m.star).map(m=>m.id));popup='';render();return}if(target.dataset.status){const s=target.dataset.status;popup='';render();document.querySelector('.status-label').textContent=s;notice('Status set to '+s);return}if(target.dataset.contact)return startCompose({to:target.dataset.contact});if(target.dataset.task){const tasks=getTasks();tasks[+target.dataset.task].done=target.checked;localStorage.setItem('gpt6-tasks',JSON.stringify(tasks));render();return}if(target.dataset.id){const m=mail.find(m=>m.id===+target.dataset.id);if(m.folder==='drafts')return startCompose({...m,subject:m.subject==='(no subject)'?'':m.subject});opened=m.id;m.read=true;persist();render()}});
